import{chromium}from'playwright';import{readFile,mkdir,writeFile}from'node:fs/promises';import{createHash}from'node:crypto';import assert from'node:assert/strict';const dir='diagnostics/seo-layout-trace-20261122';await mkdir(dir,{recursive:true});const report={scope:'Causal lab trace plus correction of audit .html path; not field CWV',activity:{},runs:[]};const r=await fetch('https://hossambahr.com/dubai-business-activities.html'),html=await r.text(),expected=await readFile('site/dubai-business-activities.html','utf8'),hash=s=>createHash('sha256').update(s).digest('hex');report.activity={status:r.status,exactSourceBytes:hash(html)===hash(expected),previousAuditIssue:'LOCAL_PATH_ENOTDIR; prior report preserved'};assert.equal(r.status,200);assert.ok(report.activity.exactSourceBytes);
const browser=await chromium.launch({headless:true,executablePath:process.env.HB_BROWSER_PATH});try{for(let i=0;i<3;i++){const page=await browser.newPage({viewport:{width:390,height:844}}),cdp=await page.context().newCDPSession(page);await cdp.send('Emulation.setCPUThrottlingRate',{rate:4});await cdp.send('Network.enable');await cdp.send('Network.emulateNetworkConditions',{offline:false,latency:150,downloadThroughput:200000,uploadThroughput:93750});await page.addInitScript(()=>{window.__trace=[];new PerformanceObserver(l=>{for(const e of l.getEntries())if(!e.hadRecentInput)window.__trace.push({time:e.startTime,value:e.value,sources:e.sources.map(s=>({tag:s.node?.tagName,id:s.node?.id,class:s.node?.className,previous:s.previousRect.toJSON(),current:s.currentRect.toJSON()}))});}).observe({type:'layout-shift',buffered:true});});await page.goto('https://hossambahr.com/services/',{waitUntil:'networkidle'});await page.waitForTimeout(1500);report.runs.push(await page.evaluate(()=>({shifts:window.__trace,cls:window.__trace.reduce((a,b)=>a+b.value,0),fonts:document.fonts.status,nodes:document.querySelectorAll('*').length})));await page.close();}}finally{await browser.close();}await writeFile(dir+'/report.json',JSON.stringify(report,null,2));console.log(JSON.stringify(report));